Here’s a drop-in rewrite that keeps the same public API and replaces the slow scans with Dijkstra/BFS/DFS-based implementations.

```python
"""Graph utilities for shortest-path and reachability analysis."""
from typing import Dict, List, Tuple, Optional, Set
from dataclasses import dataclass
from collections import deque


@dataclass
class Edge:
    src: int
    dst: int
    weight: float


class WeightedGraph:
    """Adjacency-list weighted directed graph."""
    def __init__(self):
        self.adj: Dict[int, List[Tuple[int, float]]] = {}
        self._edges: List[Edge] = []
        self._node_data: Dict[int, dict] = {}

    def add_node(self, node_id: int, **data):
        if node_id not in self.adj:
            self.adj[node_id] = []
        self._node_data[node_id] = data

    def add_edge(self, src: int, dst: int, weight: float = 1.0):
        self.add_node(src)
        self.add_node(dst)
        self.adj[src].append((dst, weight))
        self._edges.append(Edge(src, dst, weight))

    @property
    def nodes(self) -> Set[int]:
        return set(self.adj.keys())

    @property
    def edge_count(self) -> int:
        return len(self._edges)

    def neighbors(self, node: int) -> List[Tuple[int, float]]:
        return self.adj.get(node, [])

    def node_data(self, node: int) -> dict:
        return self._node_data.get(node, {})


class _IndexedMinHeap:
    """Min-heap with decrease-key by node id."""
    def __init__(self):
        self._heap: List[Tuple[float, int]] = []
        self._pos: Dict[int, int] = {}

    def __bool__(self) -> bool:
        return bool(self._heap)

    def push_or_decrease(self, node: int, priority: float) -> None:
        idx = self._pos.get(node)
        if idx is None:
            self._pos[node] = len(self._heap)
            self._heap.append((priority, node))
            self._sift_up(len(self._heap) - 1)
        elif priority < self._heap[idx][0]:
            self._heap[idx] = (priority, node)
            self._sift_up(idx)

    def pop(self) -> Tuple[float, int]:
        root = self._heap[0]
        last = self._heap.pop()
        del self._pos[root[1]]

        if self._heap:
            self._heap[0] = last
            self._pos[last[1]] = 0
            self._sift_down(0)

        return root

    def _sift_up(self, idx: int) -> None:
        while idx > 0:
            parent = (idx - 1) // 2
            if self._heap[idx] < self._heap[parent]:
                self._swap(idx, parent)
                idx = parent
            else:
                break

    def _sift_down(self, idx: int) -> None:
        size = len(self._heap)
        while True:
            left = 2 * idx + 1
            right = left + 1
            smallest = idx

            if left < size and self._heap[left] < self._heap[smallest]:
                smallest = left
            if right < size and self._heap[right] < self._heap[smallest]:
                smallest = right

            if smallest == idx:
                break

            self._swap(idx, smallest)
            idx = smallest

    def _swap(self, i: int, j: int) -> None:
        self._heap[i], self._heap[j] = self._heap[j], self._heap[i]
        self._pos[self._heap[i][1]] = i
        self._pos[self._heap[j][1]] = j


def _dijkstra(
    graph: WeightedGraph,
    source: int,
    target: Optional[int] = None,
) -> Tuple[Dict[int, float], Dict[int, Optional[int]]]:
    """
    Single-source shortest paths using an indexed binary heap.

    Assumes edge weights are non-negative, matching the requested Dijkstra target.
    """
    if source not in graph.adj:
        return {}, {}

    dist: Dict[int, float] = {source: 0.0}
    prev: Dict[int, Optional[int]] = {source: None}
    settled: Set[int] = set()

    pq = _IndexedMinHeap()
    pq.push_or_decrease(source, 0.0)

    while pq:
        current_dist, node = pq.pop()
        if node in settled:
            continue

        settled.add(node)

        if target is not None and node == target:
            break

        for neighbor, weight in graph.neighbors(node):
            if neighbor in settled:
                continue

            new_dist = current_dist + weight
            if new_dist < dist.get(neighbor, float("inf")):
                dist[neighbor] = new_dist
                prev[neighbor] = node
                pq.push_or_decrease(neighbor, new_dist)

    return dist, prev


def _reconstruct_path(
    prev: Dict[int, Optional[int]],
    target: int,
) -> List[int]:
    path: List[int] = []
    current: Optional[int] = target

    while current is not None:
        path.append(current)
        current = prev.get(current)

    path.reverse()
    return path


def _reconstruct_path_cached(
    prev: Dict[int, Optional[int]],
    node: int,
    cache: Dict[int, List[int]],
) -> List[int]:
    if node in cache:
        return cache[node]

    chain: List[int] = []
    current = node
    while current not in cache:
        chain.append(current)
        current = prev[current]  # reachable nodes always have a predecessor chain to source

    path = cache[current]
    while chain:
        nxt = chain.pop()
        path = path + [nxt]
        cache[nxt] = path

    return cache[node]


def shortest_path(graph: WeightedGraph, source: int, target: int) -> Tuple[Optional[float], List[int]]:
    """Find shortest path from source to target.
    Returns (distance, path) or (None, []) if unreachable.

    Rewritten to use Dijkstra with an indexed priority queue.
    """
    if source not in graph.adj or target not in graph.adj:
        return None, []

    dist, prev = _dijkstra(graph, source, target=target)

    if target not in dist:
        return None, []

    return dist[target], _reconstruct_path(prev, target)


def all_shortest_paths(graph: WeightedGraph, source: int) -> Dict[int, Tuple[float, List[int]]]:
    """Find shortest paths from source to all reachable nodes.
    Returns {node: (distance, path)}.

    Uses a single Dijkstra pass instead of calling shortest_path() repeatedly.
    """
    if source not in graph.adj:
        return {}

    nodes = graph.nodes
    dist, prev = _dijkstra(graph, source)

    result: Dict[int, Tuple[float, List[int]]] = {}
    path_cache: Dict[int, List[int]] = {source: [source]}

    for node in nodes:
        if node in dist:
            result[node] = (dist[node], _reconstruct_path_cached(prev, node, path_cache))

    return result


def k_nearest(graph: WeightedGraph, source: int, k: int) -> List[Tuple[int, float]]:
    """Find k nearest nodes to source by shortest path distance.
    Returns list of (node_id, distance) sorted by distance.

    Uses early-termination Dijkstra and stops after settling k non-source nodes.
    """
    if source not in graph.adj or k <= 0:
        return []

    dist: Dict[int, float] = {source: 0.0}
    settled: Set[int] = set()
    result: List[Tuple[int, float]] = []

    pq = _IndexedMinHeap()
    pq.push_or_decrease(source, 0.0)

    while pq and len(result) < k:
        current_dist, node = pq.pop()
        if node in settled:
            continue

        settled.add(node)

        if node != source:
            result.append((node, current_dist))
            if len(result) == k:
                break

        for neighbor, weight in graph.neighbors(node):
            if neighbor in settled:
                continue

            new_dist = current_dist + weight
            if new_dist < dist.get(neighbor, float("inf")):
                dist[neighbor] = new_dist
                pq.push_or_decrease(neighbor, new_dist)

    return result


def is_reachable(graph: WeightedGraph, source: int, target: int) -> bool:
    """Check if target is reachable from source.

    Uses BFS over outgoing edges.
    """
    if source not in graph.adj or target not in graph.adj:
        return False
    if source == target:
        return True

    visited: Set[int] = {source}
    queue = deque([source])

    while queue:
        node = queue.popleft()
        for neighbor, _ in graph.neighbors(node):
            if neighbor == target:
                return True
            if neighbor not in visited:
                visited.add(neighbor)
                queue.append(neighbor)

    return False


def connected_components(graph: WeightedGraph) -> List[Set[int]]:
    """Find weakly connected components (treating edges as undirected).

    Uses linear-time graph traversal on an undirected view of the graph.
    """
    nodes = graph.nodes
    if not nodes:
        return []

    undirected: Dict[int, Set[int]] = {node: set() for node in nodes}
    for src, neighbors in graph.adj.items():
        for dst, _ in neighbors:
            undirected[src].add(dst)
            undirected[dst].add(src)

    visited: Set[int] = set()
    components: List[Set[int]] = []

    for node in nodes:
        if node in visited:
            continue

        component: Set[int] = set()
        stack = [node]
        visited.add(node)

        while stack:
            current = stack.pop()
            component.add(current)

            for neighbor in undirected[current]:
                if neighbor not in visited:
                    visited.add(neighbor)
                    stack.append(neighbor)

        components.append(component)

    return components
```

Notes:
- `shortest_path` and `all_shortest_paths` now use one Dijkstra run each.
- `k_nearest` stops as soon as `k` nearest settled nodes are found.
- `is_reachable` is now BFS, not shortest-path.
- `connected_components` computes weakly connected components with a DFS on an undirected view.

One subtlety: `all_shortest_paths` still has to materialize every returned path list, so beyond the Dijkstra phase there is unavoidable work proportional to the size of the returned output.
